StructuredTextModel.Text:
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME:			 HE_AnalogInput_Logic                                                                                                                                                                                                                                                               
//	CREATOR:		 William Veim, Helgevold Elektro                                                                                                                                                                                                                                             
//                                                                                                                                                                                                                                                                                                                            
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION			DATE					SIGN							DESCRIPTION                                                                                                                                                                                                                                 
//	1.0.0					16.04.2025			William Veim				Initial Release
//	1.0.1					29.04.2025			Ruben Byman				Added alarm trigger, alarm suppression, bug fix state control action and stopped execution of Average in case of module fault
// 1.0.2					23.06.2025			Jan Magne Dybvik		Replaced Ext_AnalogValue.EXT_Operator.ProcessValue with Wrk_ProcessValue for check ProcessValueOutOfRange to avoid it interfering with itself
// 1.0.3					24.06.2025			Jan Magne Dybvik		Added HE_Real2String to create process value for SMS message
//	1.0.4					24.06.2025			Fredrik Bjerkenes 		Added HE_Real2String to create Process Value for SMS message in AlarmAnalog
// 1.0.5					24.06.2025			Jan Magne Dybvik		Moved assignment of  Ext_AnalogValue.EXT_General.Process_Unit to bottom of block
// 1.0.6					27.08.2025			William Veim				Bugfix limitation of process value
// 1.0.7					28.08.2025			William Veim				Bugfix limitation of values (only to be done if input value is signal value)
// 1.0.8					28.08.2025			William Veim				Bugfix simulating function
// 1.0.9					29.08.2025			William Veim				Temporary solution for SCADA challenge regarding symbols and STRING
// 1.0.10				04.09.2025			William Veim				Scale percent value only if in use
// 1.0.11				04.09.2025			William Veim				Rework sensor min and max value
// 1.0.12				05.09.2025			William Veim				Bugfix limitation regarding analog value (where input value is porcess value) 
// 1.0.13				08.09.2025			William Veim				Updated inistialising parameteres
// 1.0.14				10.09.2025			William Veim				Updated visibility of "Process value out of range"
// 1.0.15				23.10.2025			William Veim				Updated visibility of "Sensor min/max"
//	1.0.16				2026-01-15			William Veim				Added logic for updating symbol quality state
//	1.0.17				2026-01-21			William Veim				Calibration state set to false in case of calibration fault
//	1.0.18				2026-03-19			William Veim				Alarm suffix updated to fixed length
//	1.1.0					2026-04-28			William Veim				Added output and logic for alarm status
//	1.1.1					2026-05-29			Ruben Byman				Bugfix operating days
//	1.1.2					2026-07-07			Ruben Byman				Removed calibration timestamps, added 1s delay before calibrating to allow SCADA time to update timestamps, added temp initialize for max sensor drift
//	1.1.3					2026-07-09			Ruben Byman				Tmp Calibration Fault variables set to retain
//	1.2.0					2026-07-10			Ruben Byman				Added option to turn off analog alarm limits
//
//===============================================================================================================================
//
//		DESCRIPTION:
//		TO BE SET
//
//===============================================================================================================================

(*************************************************************************
 *	RETRIVING SYSTEM VARIABLES
 *************************************************************************)
 
 TOF_CPUStartup(In:=TRUE, PT:=TIME#10s); //10sec delay after startup (establish communication)
 Wrk_Date_Now :=DT_TO_DATE(GetTime());
 DtToDateStruct(In:=GetTime(), DateStruct=>DateStruct);
 Wrk_CurrentTime := TruncTod(DT_TO_TOD(In:=GetTime()), _SEC);
 Wrk_TimeStamp :=CONCAT(In1:=CONCAT(In1:=DateToString(Wrk_Date_Now), In2:=' '), In2:=DELETE(In:=TODToString(Wrk_CurrentTime), L:=13, P:=6));
 
 RE_MidnightPulse(Clk:=Wrk_CurrentTime=TIME_OF_DAY#00:00:00.00);
 
 (*************************************************************************
 *	INITIALIZE VARIABELS
 *************************************************************************)

Ext_AnalogValue.EXT_Alarm.Sts_SupressIfOff_Visible:=FALSE;
Ext_AnalogValue.EXT_Engineering.SignalValue_Visible :=NOT Cfg_ValueType;

//Reads input value
Wrk_InputValue:= 	Inp_Value;
Wrk_LoopBreak:=	Inp_LoopBreak;

//Unit value from wrapper block (ex. Liquiline input)
 IF Cfg_ProcessValue_Unit <> '' THEN
	 Ext_AnalogValue.EXT_General.Process_Unit:= Cfg_ProcessValue_Unit;
 END_IF;
 
 //Locking action for analog alams to "Normal/Use value"
Ext_AnalogValue.EXT_Engineering.StateCfg_1.Cfg_Action:=0; 
Ext_AnalogValue.EXT_Engineering.StateCfg_2.Cfg_Action:=0; 
Ext_AnalogValue.EXT_Engineering.StateCfg_3.Cfg_Action:=0; 
Ext_AnalogValue.EXT_Engineering.StateCfg_4.Cfg_Action:=0; 
 
IF NOT Cfg_CalibrationEnable THEN
	Ext_AnalogValue.EXT_Engineering.Calibrate_LowerVisible		:=FALSE;
	Ext_AnalogValue.EXT_Engineering.Calibrate_UpperVisible		:=FALSE;
	Ext_AnalogValue.EXT_Operator.Calibrate_Lower						:=FALSE;
	Ext_AnalogValue.EXT_Operator.Calibrate_Upper						:=FALSE;
END_IF;

//Temporary, to be removed when all PLCs are up to date
IF NOT Ext_AnalogValue.INT_Data.Tmp_Initialise_Cal THEN
	
	//Temp initialize of max sensor drift for calibration fault
	Ext_AnalogValue.EXT_Engineering.Calibration_MaxDrift:= 30;
	
	//Init complete
	Ext_AnalogValue.INT_Data.Tmp_Initialise_Cal := TRUE;
END_IF;

//Temporary 2, to be removed when all PLCs are up to date
IF NOT Ext_AnalogValue.INT_Data.Tmp_Initialise_AnalogLimits THEN
	
	//Temp initialize of activating analog alarm limits
	Ext_AnalogValue.EXT_Engineering.StateCfg_AlarmHH_Visible := TRUE;
	Ext_AnalogValue.EXT_Engineering.StateCfg_AlarmH_Visible := TRUE;
	Ext_AnalogValue.EXT_Engineering.StateCfg_AlarmL_Visible := TRUE;
	Ext_AnalogValue.EXT_Engineering.StateCfg_AlarmLL_Visible := TRUE;
	
	//Init complete
	Ext_AnalogValue.INT_Data.Tmp_Initialise_AnalogLimits := TRUE;
END_IF;
	
//Initialize
IF NOT Ext_AnalogValue.INT_Data.Initialise THEN
	
	//General parameters
	Ext_AnalogValue.EXT_General.Process_Unit:='??';
	
	//Engineering settings
	Ext_AnalogValue.EXT_Engineering.SignalValue_Scale_X0 :=Cfg_SignalValue_Y0;
	Ext_AnalogValue.EXT_Engineering.SignalValue_Scale_X1 :=Cfg_SignalValue_Y1;
	Ext_AnalogValue.EXT_Engineering.StateCfg_InputStuckTimeDelay:=100;
	Ext_AnalogValue.EXT_Engineering.StateCfg_InputStuckDiffThreshold:=0;
	Ext_AnalogValue.EXT_Engineering.Avg_NumberOfValues:=50;
	Ext_AnalogValue.EXT_Engineering.Avg_SampleInterval:=50;
	Ext_AnalogValue.EXT_Engineering.Calibration_MaxDrift:= 30;
	Ext_AnalogValue.EXT_Engineering.StateCfg_AlarmHH_Visible := TRUE;
	Ext_AnalogValue.EXT_Engineering.StateCfg_AlarmH_Visible := TRUE;
	Ext_AnalogValue.EXT_Engineering.StateCfg_AlarmL_Visible := TRUE;
	Ext_AnalogValue.EXT_Engineering.StateCfg_AlarmLL_Visible := TRUE;
	
	//State config
	Ext_AnalogValue.EXT_Engineering.StateCfg_1.Cfg_Quality:=4; //Critical high limit = Critical
	Ext_AnalogValue.EXT_Engineering.StateCfg_1.Cfg_Alarm:=TRUE; //Critical high limit = Alarm
	Ext_AnalogValue.EXT_Engineering.StateCfg_2.Cfg_Quality:=3; //Pre high limit = High
	Ext_AnalogValue.EXT_Engineering.StateCfg_2.Cfg_Alarm:=TRUE; //Pre high limit = Alarm
	Ext_AnalogValue.EXT_Engineering.StateCfg_3.Cfg_Quality:=3; //Pre low limit = High
	Ext_AnalogValue.EXT_Engineering.StateCfg_3.Cfg_Alarm:=TRUE; //Pre low limit = Alarm
	Ext_AnalogValue.EXT_Engineering.StateCfg_4.Cfg_Quality:=4; //Critical low limit = Critical
	Ext_AnalogValue.EXT_Engineering.StateCfg_4.Cfg_Alarm:=TRUE; //Critical low limit = Alarm
	Ext_AnalogValue.EXT_Engineering.StateCfg_5.Cfg_Quality:=1; //Process value out of range = Low
	Ext_AnalogValue.EXT_Engineering.StateCfg_5.Cfg_Alarm:=TRUE; //Process value out of range = Alarm
	Ext_AnalogValue.EXT_Engineering.StateCfg_6.Cfg_Quality:=1; //Input module fault = Low
	Ext_AnalogValue.EXT_Engineering.StateCfg_6.Cfg_Alarm:=TRUE; //Input module fault = Alarm
	Ext_AnalogValue.EXT_Engineering.StateCfg_7.Cfg_Quality:=0; //Value stuck = Diagnostic
	Ext_AnalogValue.EXT_Engineering.StateCfg_7.Cfg_Alarm:=TRUE; //Value stuck = Alarm
	Ext_AnalogValue.EXT_Engineering.StateCfg_8.Cfg_Quality:=0; //Calibration fault = Diagnostic
	Ext_AnalogValue.EXT_Engineering.StateCfg_8.Cfg_Alarm:=TRUE; //Calibration fault = Alarm
	Ext_AnalogValue.EXT_Engineering.StateCfg_9.Cfg_Quality:=0; //Unstable value = Diagnostic
	Ext_AnalogValue.EXT_Engineering.StateCfg_9.Cfg_Alarm:=TRUE; //Unstable value = Alarm
	
	//Alarm settings
	Ext_AnalogValue.EXT_Alarm.Cfg_SupressDelayOff:=10;
	Ext_AnalogValue.EXT_Alarm.Cfg_AlarmActiveDelay:=10;
	Ext_AnalogValue.EXT_Alarm.Cfg_AlarmReturnDelay:=10;

	//Init complete
	Ext_AnalogValue.INT_Data.Initialise:=TRUE;
	
END_IF;

//Initialise sensor min and max values (Only available when input = signal value)
IF NOT Cfg_ValueType THEN
	
	//Sensor min/max is updated according to scaling when calibration not visible in SCADA
	IF NOT Ext_AnalogValue.EXT_Engineering.Calibrate_LowerVisible AND NOT Ext_AnalogValue.EXT_Engineering.Calibrate_UpperVisible THEN
		Ext_AnalogValue.EXT_Engineering.ProcessValue_SensorMin:=		Ext_AnalogValue.EXT_Engineering.ProcessValue_Scale_Y0;
		Ext_AnalogValue.EXT_Engineering.ProcessValue_SensorMax:=		Ext_AnalogValue.EXT_Engineering.ProcessValue_Scale_Y1;
		Ext_AnalogValue.EXT_Engineering.ProcessValue_SensorLimits_Visible:=FALSE;
	ELSE
		Ext_AnalogValue.EXT_Engineering.ProcessValue_SensorLimits_Visible:=TRUE;
	END_IF;
	
	//Sensor min/max updated according to scaling when not visible in SCADA
	IF NOT Ext_AnalogValue.EXT_Engineering.ProcessValue_Percent_Visible AND NOT Ext_AnalogValue.EXT_Engineering.StateCfg_ProcessValueOutOfRange_Visible THEN
		Ext_AnalogValue.EXT_Engineering.ProcessValue_ProcessMin:=		Ext_AnalogValue.EXT_Engineering.ProcessValue_Scale_Y0;
		Ext_AnalogValue.EXT_Engineering.ProcessValue_ProcessMax:=		Ext_AnalogValue.EXT_Engineering.ProcessValue_Scale_Y1;
	END_IF;
	
ELSE //Input value = Process value
	Ext_AnalogValue.EXT_Engineering.ProcessValue_SensorLimits_Visible:=TRUE;
END_IF;

 (*************************************************************************
 *	FAULT AND STATE CONTROL
 *************************************************************************)

// FAULT CONTROL
//--------------------
IF NOT Cfg_ValueType THEN //Input value is signal value
	FB_DiffCheck.Inp_MinValue:= Cfg_SignalValue_Y0;
	FB_DiffCheck.Inp_MaxValue:= Cfg_SignalValue_Y1;
ELSE //Input value is process value
	FB_DiffCheck.Inp_MinValue:= Ext_AnalogValue.EXT_Engineering.ProcessValue_SensorMin;
	FB_DiffCheck.Inp_MaxValue:= Ext_AnalogValue.EXT_Engineering.ProcessValue_SensorMax;
END_IF;

FB_DiffCheck(ENS:=TRUE, 
							Inp_Value:=Wrk_InputValue,
							Cfg_ValueStuck_Deviation:=Ext_AnalogValue.EXT_Engineering.StateCfg_InputStuckDiffThreshold, 
							Cfg_ValueStuck_Delay:=SecToTime(Ext_AnalogValue.EXT_Engineering.StateCfg_InputStuckTimeDelay));

FB_RateOfChange(ENS:=TRUE, 
								Inp_Value:=Wrk_ProcessValue, 
								Cfg_SampleInterval:=SecToTime(Ext_AnalogValue.EXT_Engineering.StateCfg_UnstableValueTimeInterval), 
								Cfg_RateOfChange_Threshold:=Ext_AnalogValue.EXT_Engineering.StateCfg_UnstableValueThreshold, 
								Cfg_FaultAccumulated_Threshold:=10);

TON_ProcessValueOutOfRange(In:=Ext_AnalogValue.EXT_Engineering.ProcessValue_ProcessMax < Wrk_ProcessValue
														OR Ext_AnalogValue.EXT_Engineering.ProcessValue_ProcessMin > Wrk_ProcessValue, 
														PT:=TIME#10s);

HE_CalibrationFault(EXT_AnalogValue:=Ext_AnalogValue, 
								SignalValue_X0:=Cfg_SignalValue_Y0, 
								SignalValue_X1:=Cfg_SignalValue_Y1, 
								CalibrationFault_Upper=>Wrk_TmpCalibrationFault_Upper, 
								CalibrationFault_Lower=>Wrk_TmpCalibrationFault_Lower);

IF Wrk_TmpCalibrationFault_Lower THEN
	Ext_AnalogValue.EXT_Operator.Calibrate_Lower:=FALSE;
	Wrk_CalibrationFault_Lower:=TRUE;
END_IF;

IF Wrk_TmpCalibrationFault_Upper THEN
	Ext_AnalogValue.EXT_Operator.Calibrate_Upper:=FALSE;
	Wrk_CalibrationFault_Upper:=TRUE;
END_IF;

Wrk_InputStuck:= FB_DiffCheck.Out_ValueStuck;

Wrk_UnstableValue:=FB_RateOfChange.Out_Fault;

Wrk_ProcessValueOutOfRange := TON_ProcessValueOutOfRange.Q;

Wrk_ModuleFault:= Inp_ModuleFault AND TOF_CPUStartup.Q;

//Resetter variabler før løkke
Ext_AnalogValue.EXT_General.Sts_Quality := 6; //Good
Wrk_ActionState:=	0;

//Critical high limit
HE_StateControl(EXT_StateData:=Ext_AnalogValue.EXT_Engineering.StateCfg_1, 
							Inp_Visibility:=Ext_AnalogValue.EXT_Engineering.StateCfg_AlarmHH_Visible, 
							Inp_State:=(Ext_AnalogValue.EXT_Operator.ProcessValue > Ext_AnalogValue.EXT_AlarmAnalog.Cfg_Limit_HH) AND NOT Inp_LoopBreak AND NOT Inp_ModuleFault, 
							Inp_Desc:='High-high limit', 
							Sts_Quality:=Ext_AnalogValue.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[0].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[0].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[0].Alm_Priority);

//Pre high limit
HE_StateControl(EXT_StateData:=Ext_AnalogValue.EXT_Engineering.StateCfg_2, 
							Inp_Visibility:=Ext_AnalogValue.EXT_Engineering.StateCfg_AlarmH_Visible, 
							Inp_State:=(Ext_AnalogValue.EXT_Operator.ProcessValue > Ext_AnalogValue.EXT_AlarmAnalog.Cfg_Limit_H) AND NOT Inp_LoopBreak AND NOT Inp_ModuleFault, 
							Inp_Desc:='High limit', 
							Sts_Quality:=Ext_AnalogValue.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[1].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[1].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[1].Alm_Priority);

//Pre low limit
HE_StateControl(EXT_StateData:=Ext_AnalogValue.EXT_Engineering.StateCfg_3, 
							Inp_Visibility:=Ext_AnalogValue.EXT_Engineering.StateCfg_AlarmL_Visible, 
							Inp_State:=(Ext_AnalogValue.EXT_Operator.ProcessValue < Ext_AnalogValue.EXT_AlarmAnalog.Cfg_Limit_L) AND NOT Inp_LoopBreak AND NOT Inp_ModuleFault, 
							Inp_Desc:='Low limit', 
							Sts_Quality:=Ext_AnalogValue.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[2].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[2].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[2].Alm_Priority);

//Critical low limit
HE_StateControl(EXT_StateData:=Ext_AnalogValue.EXT_Engineering.StateCfg_4, 
							Inp_Visibility:=Ext_AnalogValue.EXT_Engineering.StateCfg_AlarmLL_Visible, 
							Inp_State:=(Ext_AnalogValue.EXT_Operator.ProcessValue < Ext_AnalogValue.EXT_AlarmAnalog.Cfg_Limit_LL) AND NOT Inp_LoopBreak AND NOT Inp_ModuleFault, 
							Inp_Desc:='Low-low limit', 
							Sts_Quality:=Ext_AnalogValue.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[3].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[3].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[3].Alm_Priority);

//Process value out of range
HE_StateControl(EXT_StateData:=Ext_AnalogValue.EXT_Engineering.StateCfg_5, 
							Inp_Visibility:=Ext_AnalogValue.EXT_Engineering.StateCfg_ProcessValueOutOfRange_Visible, 
							Inp_State:=Wrk_ProcessValueOutOfRange, 
							Inp_Desc:='Process value out of range', 
							Sts_Quality:=Ext_AnalogValue.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[4].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[4].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[4].Alm_Priority);

//Module fault
HE_StateControl(EXT_StateData:=Ext_AnalogValue.EXT_Engineering.StateCfg_6, 
							Inp_Visibility:=TRUE, 
							Inp_State:=Wrk_ModuleFault, 
							Inp_Desc:='Input module fault', 
							Sts_Quality:=Ext_AnalogValue.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[5].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[5].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[5].Alm_Priority);

//Value Stuck
HE_StateControl(EXT_StateData:=Ext_AnalogValue.EXT_Engineering.StateCfg_7, 
							Inp_Visibility:=Ext_AnalogValue.EXT_Engineering.StateCfg_InputStuckVisible, 
							Inp_State:=Wrk_InputStuck, 
							Inp_Desc:='Value stuck', 
							Sts_Quality:=Ext_AnalogValue.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[6].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[6].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[6].Alm_Priority);

//Calibration fault
HE_StateControl(EXT_StateData:=Ext_AnalogValue.EXT_Engineering.StateCfg_8, 
							Inp_Visibility:=Ext_AnalogValue.EXT_Engineering.Calibrate_LowerVisible OR Ext_AnalogValue.EXT_Engineering.Calibrate_UpperVisible, 
							Inp_State:=Wrk_CalibrationFault_Lower OR Wrk_CalibrationFault_Upper, 
							Inp_Desc:='Calibration fault', 
							Sts_Quality:=Ext_AnalogValue.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[7].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[7].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[7].Alm_Priority);

//Unstable value
HE_StateControl(EXT_StateData:=Ext_AnalogValue.EXT_Engineering.StateCfg_9, 
							Inp_Visibility:=Ext_AnalogValue.EXT_Engineering.StateCfg_UnstableValueVisible, 
							Inp_State:=Wrk_UnstableValue, 
							Inp_Desc:='Unstable value', 
							Sts_Quality:=Ext_AnalogValue.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[8].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[8].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[8].Alm_Priority);

//According to input
HE_StateControl(EXT_StateData:=Ext_AnalogValue.EXT_Engineering.StateCfg_10, 
							Inp_Visibility:=Cfg_State10_InUse, 
							Inp_State:=Inp_State10_State, 
							Inp_Desc:=Inp_State10_Desc, 
							Sts_Quality:=Ext_AnalogValue.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[9].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[9].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[9].Alm_Priority);

//According to input
HE_StateControl(EXT_StateData:=Ext_AnalogValue.EXT_Engineering.StateCfg_11, 
							Inp_Visibility:=Cfg_State11_InUse, 
							Inp_State:=Inp_State11_State, 
							Inp_Desc:=Inp_State11_Desc, 
							Sts_Quality:=Ext_AnalogValue.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[10].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[10].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[10].Alm_Priority);

//According to input
HE_StateControl(EXT_StateData:=Ext_AnalogValue.EXT_Engineering.StateCfg_12, 
							Inp_Visibility:=Cfg_State12_InUse, 
							Inp_State:=Inp_State12_State, 
							Inp_Desc:=Inp_State12_Desc, 
							Sts_Quality:=Ext_AnalogValue.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[11].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[11].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[11].Alm_Priority);

//State control action
//---------------------

 IF TOF_CPUStartup.Q THEN

	CASE Wrk_ActionState OF
		
		0://Use value
		Ext_AnalogValue.EXT_Operator.ProcessValue:= Wrk_ProcessValue;
		
		1://Hold value
		Ext_AnalogValue.EXT_Operator.ProcessValue:= Ext_AnalogValue.EXT_Operator.ProcessValue;
		
		2://Pre defined output
		Ext_AnalogValue.EXT_Operator.ProcessValue:= Ext_AnalogValue.EXT_Engineering.StateCfg_PreDefinedValue;
		
	END_CASE;	
 ELSE
	 Ext_AnalogValue.EXT_Operator.ProcessValue:= Ext_AnalogValue.EXT_Operator.ProcessValue;
 END_IF;

(*************************************************************************
 *	EXCECUTING ALARM BLOCK
 *************************************************************************)
 
 FB_AlarmLogic(ENS:=TRUE, 
								 Ext_Alarm:=Ext_AnalogValue.EXT_Alarm, 
								 Int_Alarm:=Int_Alarm, 
								 Inp_AlarmData:=Wrk_AlarmData,
								 Inp_LocationData:=Ext_AnalogValue.EXT_General.LocationIndex,
								 Inp_AlarmSupress:=Inp_AlmSuppress, 
								 Inp_AlmSuppressDesc:=Inp_AlmSuppressDesc, 
								 Inp_Connected_Cabinet:=Cfg_ControlCabinet, 
								 Inp_Connected_Controller:=Cfg_ControllerTAG, 
								 Inp_Process_TAG:=Cfg_ProcessTAG, 
								 Inp_Process_Desc:=Ext_AnalogValue.EXT_General.Process_Desc,
								 Out_AlarmToken=>Wrk_AlarmToken, 
								 Out_AlarmTriggered=>Wrk_AlarmTriggered,
								 Inp_Process_Value:= CONCAT(RealToFormatString(Ext_AnalogValue.EXT_Operator.ProcessValue,FALSE,FALSE,2,2), Ext_AnalogValue.EXT_General.Process_Unit));

(*************************************************************************
 *	CALIBRATION (X0, X1, Y0, Y1 CONTROL)
 *************************************************************************)

//Delay timers for calibration
TON_CalibrationLower(In:=(Ext_AnalogValue.EXT_Operator.Calibrate_Lower AND Ext_AnalogValue.EXT_Engineering.Calibrate_LowerVisible), PT:=T#1s);
TON_CalibrationUpper(In:=(Ext_AnalogValue.EXT_Operator.Calibrate_Upper AND Ext_AnalogValue.EXT_Engineering.Calibrate_UpperVisible), PT:=T#1s);

IF NOT Cfg_ValueType THEN
	
	//No lower calibration
	IF NOT Ext_AnalogValue.EXT_Engineering.Calibrate_LowerVisible THEN
		Ext_AnalogValue.EXT_Engineering.SignalValue_Scale_X0			:= Cfg_SignalValue_Y0;
		Ext_AnalogValue.EXT_Operator.Calibrate_Lower							:= FALSE;
	END_IF;
	
	//No upper calibration
	IF NOT Ext_AnalogValue.EXT_Engineering.Calibrate_UpperVisible THEN
		Ext_AnalogValue.EXT_Engineering.SignalValue_Scale_X1			:= Cfg_SignalValue_Y1;
		Ext_AnalogValue.EXT_Operator.Calibrate_Upper							:= FALSE;
	END_IF;

	//Lower calibration (X0-Y0)
	IF TON_CalibrationLower.Q THEN
		Ext_AnalogValue.EXT_Engineering.SignalValue_Scale_X0 		:= Wrk_InputValue;
		Ext_AnalogValue.EXT_Engineering.ProcessValue_Scale_Y0 		:= Ext_AnalogValue.EXT_Operator.CalibrateValue_Lower;
		Ext_AnalogValue.EXT_Operator.Calibrate_Lower 					:= FALSE;
		Wrk_CalibrationFault_Lower													:= FALSE;
	END_IF;

	//Upper calibration (X1-Y1)
	IF TON_CalibrationUpper.Q THEN
		Ext_AnalogValue.EXT_Engineering.SignalValue_Scale_X1 		:= Wrk_InputValue;
		Ext_AnalogValue.EXT_Engineering.ProcessValue_Scale_Y1 		:= Ext_AnalogValue.EXT_Operator.CalibrateValue_Upper;
		Ext_AnalogValue.EXT_Operator.Calibrate_Upper						:= FALSE;
		Wrk_CalibrationFault_Upper													:= FALSE;
	END_IF;
	
END_IF; 
 
 (*************************************************************************
 *	SIMULATION OF PROCESS OR SIGNAL VALUE
 *************************************************************************)
 
IF NOT Cfg_ValueType THEN //Input value is signal value (mA value)
	
	 //Simulate process value		
	 IF Ext_AnalogValue.EXT_Engineering.Simulate_ProcessValue_Active THEN
		 
		 Wrk_InputValue:= ScaleTrans(SclIn:=Ext_AnalogValue.EXT_Engineering.Simulate_ProcessValue_Value, 
														 X0:=Ext_AnalogValue.EXT_Engineering.ProcessValue_Scale_Y0, 
														 Y0:=Ext_AnalogValue.EXT_Engineering.SignalValue_Scale_X0, 
														 X1:=Ext_AnalogValue.EXT_Engineering.ProcessValue_Scale_Y1, 
														 Y1:=Ext_AnalogValue.EXT_Engineering.SignalValue_Scale_X1);
		 Ext_AnalogValue.EXT_General.Sts_Quality:=5; //QUALITY TO SIMULATE
		 
	 //Simulate signal value		 
	 ELSIF Ext_AnalogValue.EXT_Engineering.Simulate_SignalValue_Active THEN
		 
		 Wrk_InputValue:= Ext_AnalogValue.EXT_Engineering.Simulate_SignalValue_Value;
		 Ext_AnalogValue.EXT_General.Sts_Quality:=5; //QUALITY TO SIMULATE
		 
	 END_IF;
 
ELSE //Input value is process value
	
	IF Ext_AnalogValue.EXT_Engineering.Simulate_ProcessValue_Active THEN
		
		Wrk_InputValue:=Ext_AnalogValue.EXT_Engineering.Simulate_ProcessValue_Value;
		Ext_AnalogValue.EXT_General.Sts_Quality:=5; //QUALITY TO SIMULATE
		
	END_IF;
	
END_IF;
 
 IF Ext_AnalogValue.EXT_Engineering.Simulate_ProcessValue_Active
	 AND Ext_AnalogValue.EXT_Engineering.Simulate_SignalValue_Active THEN
	 
	 Ext_AnalogValue.EXT_Engineering.Simulate_ProcessValue_Active:=FALSE;
	 
 END_IF;
 
 IF Cfg_ValueType THEN 
	 
 	Ext_AnalogValue.EXT_Engineering.Simulate_SignalValue_Active:=FALSE;
	
 END_IF;

//Limits simulation signal value (limits to block min and max)
Ext_AnalogValue.EXT_Engineering.Simulate_SignalValue_Value:=LIMIT(MN:=Cfg_SignalValue_Y0, 
																													In:=Ext_AnalogValue.EXT_Engineering.Simulate_SignalValue_Value, 
																													MX:=Cfg_SignalValue_Y1);

 (*************************************************************************
 *	INPUT VALUE CONTROL AND AVERAGE 
 *************************************************************************)
 
//AVERAGE INPUT VALUE
FB_Average(
	ENS									:=NOT Wrk_ModuleFault AND NOT Wrk_LoopBreak,
	Inp_Value							:=	Wrk_InputValue, 
	Cfg_NumberOfValues		:= Ext_AnalogValue.EXT_Engineering.Avg_NumberOfValues, 
	Cfg_SamplingInterval		:=	Ext_AnalogValue.EXT_Engineering.Avg_SampleInterval);

Ext_AnalogValue.EXT_Engineering.Avg_CalculatedTime:= (UINT_TO_REAL(Ext_AnalogValue.EXT_Engineering.Avg_NumberOfValues) * UINT_TO_REAL(Ext_AnalogValue.EXT_Engineering.Avg_SampleInterval)) /1000;
 
//INPUT VALUE = SIGNAL VALUE
//----------------------------------
IF NOT Cfg_ValueType THEN
	
	IF NOT Wrk_LoopBreak OR Ext_AnalogValue.EXT_Engineering.Simulate_ProcessValue_Active OR Ext_AnalogValue.EXT_Engineering.Simulate_SignalValue_Active THEN
		
	Ext_AnalogValue.EXT_Engineering.SignalValue :=  					FB_Average.Out_Average;
	Wrk_ProcessValue :=																ScaleTrans(SclIn:=Ext_AnalogValue.EXT_Engineering.SignalValue, 
																														X0:=Ext_AnalogValue.EXT_Engineering.SignalValue_Scale_X0, 
																														Y0:=Ext_AnalogValue.EXT_Engineering.ProcessValue_Scale_Y0, 
																														X1:=Ext_AnalogValue.EXT_Engineering.SignalValue_Scale_X1, 
																														Y1:=Ext_AnalogValue.EXT_Engineering.ProcessValue_Scale_Y1);
	ELSE
		
		Ext_AnalogValue.EXT_Engineering.SignalValue:= Ext_AnalogValue.EXT_Engineering.SignalValue / Wrk_Dummy; //Might look for a better solution
		Wrk_ProcessValue :=Wrk_ProcessValue / Wrk_Dummy;
		
	END_IF;

//Limits scaling values
Ext_AnalogValue.EXT_Engineering.SignalValue_Scale_X0:=LIMIT(MN:=Cfg_SignalValue_Y0, 
																												In:=Ext_AnalogValue.EXT_Engineering.SignalValue_Scale_X0, 
																												MX:=Cfg_SignalValue_Y1);

Ext_AnalogValue.EXT_Engineering.SignalValue_Scale_X1:=LIMIT(MN:=Cfg_SignalValue_Y0, 
																												In:=Ext_AnalogValue.EXT_Engineering.SignalValue_Scale_X1, 
																												MX:=Cfg_SignalValue_Y1);

//INPUT VALUE = PROCESS VALUE
//------------------------------------
ELSE	
	
	Ext_AnalogValue.EXT_Engineering.SignalValue_Visible :=		FALSE;
	Wrk_ProcessValue :=																FB_Average.Out_Average;
	
END_IF;

//Adds offset
IF Ext_AnalogValue.EXT_Engineering.Offset_Visible THEN
	Wrk_ProcessValue:=Wrk_ProcessValue+Ext_AnalogValue.EXT_Operator.OffsetValue;
END_IF;

//Scaling percent
IF Ext_AnalogValue.EXT_Engineering.ProcessValue_Percent_Visible THEN
	
Ext_AnalogValue.EXT_Operator.ProcessValue_Percent:=	 ScaleTrans(SclIn:=Ext_AnalogValue.EXT_Operator.ProcessValue, 
																											X0:=Ext_AnalogValue.EXT_Engineering.ProcessValue_ProcessMin, 
																											Y0:=0, 
																											X1:=Ext_AnalogValue.EXT_Engineering.ProcessValue_ProcessMax, 
																											Y1:=100);
ELSE
	
	Ext_AnalogValue.EXT_Operator.ProcessValue_Percent:=0;
	
END_IF;

IF NOT Cfg_ValueType THEN //Input value is signal value (mA value)
	
	IF NOT Inp_LoopBreak THEN 
		Ext_AnalogValue.EXT_Operator.ProcessValue:=LIMIT(MN:=Ext_AnalogValue.EXT_Engineering.ProcessValue_SensorMin, 
																							In:=Ext_AnalogValue.EXT_Operator.ProcessValue, 
																							MX:=Ext_AnalogValue.EXT_Engineering.ProcessValue_SensorMax);
	END_IF;
	
Ext_AnalogValue.EXT_Engineering.ProcessValue_Scale_Y0:=LIMIT(MN:=Ext_AnalogValue.EXT_Engineering.ProcessValue_SensorMin, 
																										In:=Ext_AnalogValue.EXT_Engineering.ProcessValue_Scale_Y0, 
																										MX:=Ext_AnalogValue.EXT_Engineering.ProcessValue_SensorMax);

Ext_AnalogValue.EXT_Engineering.ProcessValue_Scale_Y1:=LIMIT(MN:=Ext_AnalogValue.EXT_Engineering.ProcessValue_SensorMin, 
																										In:=Ext_AnalogValue.EXT_Engineering.ProcessValue_Scale_Y1, 
																										MX:=Ext_AnalogValue.EXT_Engineering.ProcessValue_SensorMax);

Ext_AnalogValue.EXT_Engineering.ProcessValue_ProcessMin:=LIMIT(MN:=Ext_AnalogValue.EXT_Engineering.ProcessValue_SensorMin, 
																										In:=Ext_AnalogValue.EXT_Engineering.ProcessValue_ProcessMin, 
																										MX:=Ext_AnalogValue.EXT_Engineering.ProcessValue_SensorMax);

Ext_AnalogValue.EXT_Engineering.ProcessValue_ProcessMax:=LIMIT(MN:=Ext_AnalogValue.EXT_Engineering.ProcessValue_SensorMin, 
																										In:=Ext_AnalogValue.EXT_Engineering.ProcessValue_ProcessMax, 
																										MX:=Ext_AnalogValue.EXT_Engineering.ProcessValue_SensorMax);

END_IF;

(*************************************************************************
 *	STATISTIC DATA
 *************************************************************************)
 
 IF Inp_RstOperatingTime THEN
	 Wrk_OperatingHours:=TIME#0s;
	 Ext_AnalogValue.EXT_Statistics.Date_ResetOperatingDays := DateToString(Wrk_Date_Now);
 ELSIF Ext_AnalogValue.EXT_Statistics.Date_ResetOperatingDays = '' THEN
	 Ext_AnalogValue.EXT_Statistics.Date_ResetOperatingDays := DateToString(Wrk_Date_Now);
 END_IF;
 
 IF NOT Inp_LoopBreak THEN
 Wrk_OperatingHours:= ADD_TIME(Wrk_OperatingHours,GetMyTaskInterval());
 END_IF;
 
 Ext_AnalogValue.EXT_Statistics.OperatingDays:= LINT_TO_UINT(TimeToSec(Wrk_OperatingHours)/3600/24);
 
 //Checks if new day
 IF Sample_Day <> DateStruct.Day THEN
	 Ext_AnalogValue.EXT_Statistics.MinValue_Today:=Ext_AnalogValue.EXT_Operator.ProcessValue;
	 Ext_AnalogValue.EXT_Statistics.MaxValue_Today:=Ext_AnalogValue.EXT_Operator.ProcessValue;
	 Sample_Day:=DateStruct.Day;
 END_IF;
 
 IF Ext_AnalogValue.EXT_Operator.ProcessValue > Ext_AnalogValue.EXT_Statistics.MaxValue_Today THEN
	 Ext_AnalogValue.EXT_Statistics.MaxValue_Today:=Ext_AnalogValue.EXT_Operator.ProcessValue;
 END_IF;
 
  IF Ext_AnalogValue.EXT_Operator.ProcessValue < Ext_AnalogValue.EXT_Statistics.MinValue_Today THEN
	 Ext_AnalogValue.EXT_Statistics.MinValue_Today:=Ext_AnalogValue.EXT_Operator.ProcessValue;
 END_IF;
 
(*************************************************************************
 *	UPDATING STRUCTURE DATA
 *************************************************************************)
 
 //Temp solution for SCADA trouble
 IF Ext_AnalogValue.EXT_General.Process_Unit = 'degC' OR Ext_AnalogValue.EXT_General.Process_Unit = 'DegC' THEN
	 Ext_AnalogValue.EXT_General.Process_Unit:='°C';
 ELSIF Ext_AnalogValue.EXT_General.Process_Unit = 'm3/h' THEN
	 Ext_AnalogValue.EXT_General.Process_Unit:='m³/h';
 END_IF;
 
 Ext_AnalogValue.EXT_Engineering.SignalValue_Unit:=					Cfg_SignalValue_Unit;
 Ext_AnalogValue.EXT_General.Process_TAG:=								Cfg_ProcessTAG;
 Ext_AnalogValue.EXT_General.Connected_ControlCabinet:=			Cfg_ControlCabinet;
 Ext_AnalogValue.EXT_General.Controlled_FromController:=			Cfg_ControllerTAG;
 
 (*************************************************************************
 *	UPDATING OUTPUT DATA
 *************************************************************************)
 
//OUTPUT
Sts_AlarmToken:=Wrk_AlarmToken;
Sts_AlarmTriggered:=Wrk_AlarmTriggered;
